#!/usr/bin/env node
// Generates the plugin's eval suites from eval-src/. Do not edit the generated
// files by hand; edit eval-src/ and run `npm run eval:build`.
//
//   plugin/evals/       Claude Code and Cowork: the MCP server is there (answered from
//                       recorded mocks), with an empty Career KB unless a case says otherwise
//   plugin/evals-chat/  Claude.ai: no MCP tools at all, so the skill has to work from
//                       what the user pastes. Also holds the trigger suite, since the
//                       Skill tool is then the only way the plugin can show up.

import { cpSync, existsSync, mkdirSync, readdirSync, readFileSync, rmSync, writeFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";
import { parse } from "yaml";
import { CHAT_TASKS, FIRST_CONTACT_POSTING_ONLY, MEMORY_CASES } from "./cases.mjs";

const here = dirname(fileURLToPath(import.meta.url));
const repo = join(here, "..");
// EVAL_SUITE_ROOT lets the sync test generate into a scratch folder and compare.
const OUT = process.env.EVAL_SUITE_ROOT ?? join(repo, "plugin");
const TOOLS_SUITE = join(OUT, "evals");
const CHAT_SUITE = join(OUT, "evals-chat");
const MCP = "mcp__plugin_career-compass_career-compass__";
const SKILLS = "career-compass|fit-check|start|today|interview-prep";

// ---------- inputs ----------

function readFront(file) {
  const text = readFileSync(file, "utf-8");
  const m = text.match(/^---\n([\s\S]*?)\n---\n([\s\S]*)$/);
  return { ...parse(m[1]), body: m[2].trim() };
}

function loadDir(dir) {
  const out = {};
  for (const f of readdirSync(join(here, dir)).filter((f) => f.endsWith(".md"))) {
    const item = readFront(join(here, dir, f));
    out[item.id] = item;
  }
  return out;
}

const personas = loadDir("personas");
const postings = loadDir("postings");
const lines = (f) => readFileSync(join(here, "trigger", f), "utf-8").split("\n").map((l) => l.trim()).filter((l) => l && !l.startsWith("#"));

// ---------- writers ----------

function yamlList(items) {
  return `[${items.join(", ")}]`;
}

function frontmatter(fields) {
  const out = Object.entries(fields).filter(([, v]) => v !== undefined).map(([k, v]) => {
    if (Array.isArray(v)) return `${k}: ${yamlList(v)}`;
    if (typeof v === "string" && /[:#'"\n]|^\s|\s$/.test(v)) return `${k}: '${v.replaceAll("'", "''")}'`;
    return `${k}: ${v}`;
  });
  return `---\n${out.join("\n")}\n---\n`;
}

function writeCase(suite, name, { prompt, tags, graders, maxTurns = 12, description }) {
  const dir = join(suite, name);
  mkdirSync(join(dir, "graders"), { recursive: true });
  writeFileSync(join(dir, "prompt.md"), `${frontmatter({
    description,
    tags,
    max_turns: maxTurns,
    timeout_seconds: 300,
    allowed_tools: ["Skill"],
  })}\n${prompt.trim()}\n`);
  for (const [file, { body = "", ...fields }] of Object.entries(graders)) {
    writeFileSync(join(dir, "graders", `${file}.md`), `${frontmatter(fields)}${body ? `\n${body.trim()}\n` : ""}`);
  }
  return dir;
}

function resetSuite(suite) {
  mkdirSync(suite, { recursive: true });
  for (const entry of readdirSync(suite)) {
    if (entry === "results") continue; // run output, git-ignored
    rmSync(join(suite, entry), { recursive: true, force: true });
  }
  writeFileSync(join(suite, "GENERATED.md"),
    "Generated by `npm run eval:build` from `eval-src/`. Edit there, not here.\n" +
    "See eval-src/README.md for how to run the suite and read the scoreboard.\n");
}

// ---------- graders ----------

const skillFired = {
  type: "tool_used", tool: "Skill",
  input_match: `"skill"\\s*:\\s*"(?:career-compass:)?(${SKILLS})"`,
};

function honesty(p) {
  return {
    type: "llm", weight: 2,
    body: `
PASS if every employer, job title, date, number, skill, tool, credential, team size and achievement that the reply presents as true of ${p.name} (the user) appears in their résumé below or in their own message.
FAIL if the reply states as fact something about ${p.name} that is not in the résumé below, such as an invented metric, a tool or skill they never listed, or experience in one of the "not stated" areas, including in drafted résumé bullets, cover letters, or interview answers written in their voice.

Not failures: advice; opinions and characterizations (such as calling a degree "quantitative-adjacent"); simple arithmetic from the résumé (such as years computed from its dates); questions to the user; placeholders clearly marked for the user to fill in; and anything said about the job, the employer, the posting or the job market, which this check ignores.

Not stated anywhere: ${p.not_stated}.

${p.name}'s résumé, which is everything known about them:

${p.body.split("\n").map((l) => `    ${l}`).join("\n")}`,
  };
}

function kbHonesty() {
  // The whole saved KB, not just experience: the journal, projects, skills and
  // education all hold facts the assistant may rightly use.
  const dir = join(repo, "data", "example", "career");
  const kb = readdirSync(dir).filter((f) => f.endsWith(".yaml")).sort()
    .map((f) => `--- ${f}\n${readFileSync(join(dir, f), "utf-8").replace(/^#.*\n/gm, "").trim()}`)
    .join("\n\n");
  return {
    type: "llm", weight: 2,
    body: `
PASS if every number, employer, title, project, credential and achievement the reply presents as true of Alex Rivera (the user) is supported by their saved Career KB below or by their own message.
FAIL if the reply states as fact a metric, employer, credential, project or achievement for Alex Rivera that the KB below does not support, or changes one of its numbers.

Not failures: advice; opinions; restating the KB's own summary (for example "9 years of experience"); simple arithmetic from the KB; questions to the user; placeholders clearly marked for the user to fill in; and anything said about the job, the employer or the job market, which this check ignores.

Alex Rivera's saved Career KB (YAML files):

${kb.split("\n").map((l) => `    ${l}`).join("\n")}`,
  };
}

function fitRubric(post) {
  return {
    type: "llm", weight: 2,
    body: `
The user asked how well they fit a job posting. Expected verdict: ${post.verdict}. Their strongest evidence: ${post.strengths}. The real gaps: ${post.gaps}.

PASS if the reply does all of these: gives a clear overall verdict near the top (for example strong fit, stretch, or long shot, or a score) that is at most one step from the expected verdict on the scale strong, stretch, long shot; ties at least two specific items from the user's background to specific requirements in the posting; names the most important gap above plainly; and ends with a concrete next step.
FAIL if the verdict is missing or is two steps away from the expected one (calling a long shot a strong fit, or the reverse), if the support is generic praise rather than specific evidence, or if the most important gap goes unmentioned.`,
  };
}

function taskRubric(t, post) {
  const strengths = post?.strengths;
  const gaps = post?.gaps;
  switch (t.task) {
    case "tailor": return { type: "llm", weight: 2, body: `
The user asked for their résumé tailored to a posting. Their strongest relevant evidence: ${strengths}. Gaps that cannot honestly be papered over: ${gaps}.

PASS if the reply contains rewritten résumé content (a summary and bullets, or a full draft) aimed at this posting, leads with the strongest relevant evidence above, uses the posting's language only where it is true, and tells the user about any gap or any claim they need to confirm.
FAIL if the reply gives only general advice with no rewritten content, drops the strongest evidence above, or covers a gap by implying experience the user does not have.` };
    case "cover": return { type: "llm", weight: 2, body: `
The user asked for a cover letter. Their strongest relevant evidence: ${strengths}. It must also handle ${t.special}.

PASS if the reply contains a complete letter for this role at this company, opens with something specific rather than "I am writing to apply for", uses at least two concrete achievements from the user's background that match the posting, handles the point above well, and is short enough to read in a minute (roughly 400 words or fewer).
FAIL if the letter is generic enough to send to any job, names the wrong company or role, leans on filler adjectives instead of evidence, or skips or mishandles the point above.` };
    case "interview": return { type: "llm", weight: 2, body: `
The user asked for interview prep. Weak spots an interviewer is likely to probe: ${gaps}.

PASS if the reply includes likely questions specific to this role and round, at least three STAR-style stories built from real items in the user's background, an honest plan for the weak spots above, and a few questions for the user to ask. It must be easy to follow for this user.
FAIL if the questions are generic to any job, the stories are not grounded in the user's actual background, or the weak spots above are ignored.` };
    case "offer": return { type: "llm", weight: 2, body: `
The user, currently on a $285,000 base as VP of Engineering and looking for a CTO or SVP role, asked whether a Northbeam SVP of Engineering offer is good: $310,000 base, 20% bonus target, 0.35% options with 4-year vesting and a 1-year cliff, start in 3 weeks, offer expires in 5 business days.

PASS if the reply compares the offer to the user's current $285,000 base and to their stated goal (an SVP role fits it); notes the equity can't be valued without the company's valuation, share count or strike price and says what to ask for; gives two or three specific negotiation points with suggested wording; and addresses the 5-day deadline.
FAIL if it presents invented market data as fact, values the equity in dollars without the needed information, or gives generic "always negotiate" advice without specific points.` };
    case "recruiter": return { type: "llm", weight: 2, body: `
The user, a contractor with 6 years of short front-end contracts, got a recruiter email for a 6-month contract-to-hire at Harborline Insurance, $70/hr W2, remote, React, TypeScript and accessibility.

PASS if the reply gives a clear read on whether it is worth pursuing, connects it to the user's real background (React and TypeScript, WCAG work, the insurance quote form rebuild at Kestrel Insurance), points out what to clarify (conversion terms and salary on conversion, benefits on W2, how $70/hr compares to the posted full-time range if known), and drafts a short reply to the recruiter.
FAIL if there is no drafted reply, the advice ignores the contract-to-hire terms, or it invents facts about Harborline or the user.` };
    default: throw new Error(`unknown task ${t.task}`);
  }
}

const valueFirst = {
  type: "llm", weight: 2,
  body: `
This is the user's first message to a job-search assistant. They pasted a résumé and a job posting and asked a direct question.

PASS if this reply delivers the answer to that question itself (a fit assessment, with a verdict) without first asking the user to set anything up, install anything, or answer a list of questions. Up to two follow-up questions after the answer are fine.
FAIL if the reply mostly asks questions, describes what it could do instead of doing it, or puts setup steps before the answer.`,
};

const postingOnlyFirstReply = {
  type: "llm", weight: 2,
  body: `
This is the user's first message to a job-search assistant. They pasted only a job posting and asked whether they fit. The assistant has no information about the user yet.

PASS if the reply makes it easy to get a real answer: its main ask is for their résumé or LinkedIn experience, pasted in, and it may also give a useful read of the posting (its must-haves, what the employer is screening for). One short optional question beside the résumé ask (such as their salary target) is fine.
FAIL if the reply invents a fit verdict for a person it knows nothing about, asks three or more separate questions, or asks the user to fill in files, run commands, or complete setup before helping.`,
};

const mentionsLocalMode = {
  type: "regex", weight: 0.5,
  pattern: "Claude Code|Cowork",
};

const noFalseSaveClaim = {
  type: "regex",
  pattern: "(I'?ve|I have) (now )?(saved|stored|recorded|added|tracked)|(saved|stored) (it|this|that|your)",
  flags: "i", match: "not_contains",
};

const noUnaskedWrite = (tool) => ({ type: "tool_used", tool: `${MCP}${tool}`, min: 0, max: 0 });

// ---------- assemble ----------

function resumeAndPosting(p, post, ask) {
  return `Here's my résumé:\n\n${p.body}\n\nAnd the job:\n\n${post.body}\n\n${ask}`;
}

const FIT_ASKS = {
  "new-grad": "Do I have a real shot at this one?",
  "laid-off-engineer": "How well do I fit this? I need to start applying this week.",
  "career-switcher": "Am I qualified for this or am I kidding myself?",
  "senior-pm": "How well do I fit this role?",
  "executive": "Is this worth pursuing?",
  "return-to-work": "How do I stack up for this after my break?",
  "non-native": "this job is good for me? how much i fit?",
  "contractor": "How well do I match this full-time role?",
};

function postingFor(personaId) {
  return Object.values(postings).find((p) => p.persona === personaId);
}

function buildChat() {
  resetSuite(CHAT_SUITE);
  let n = 0;
  lines("should-fire.txt").forEach((prompt, i) => {
    writeCase(CHAT_SUITE, `trigger-fire-${String(i + 1).padStart(2, "0")}`, {
      prompt, tags: ["trigger", "should-fire"], maxTurns: 4,
      graders: { "activation--skill-fired": skillFired },
    }); n++;
  });
  lines("should-not-fire.txt").forEach((prompt, i) => {
    writeCase(CHAT_SUITE, `trigger-quiet-${String(i + 1).padStart(2, "0")}`, {
      prompt, tags: ["trigger", "should-not-fire"], maxTurns: 4,
      graders: { "activation--no-false-fire": { ...skillFired, min: 0, max: 0, arm: "both" } },
    }); n++;
  });
  for (const [id, p] of Object.entries(personas)) {
    const post = postingFor(id);
    writeCase(CHAT_SUITE, `chat-first-contact-${id}`, {
      description: p.why,
      prompt: resumeAndPosting(p, post, FIT_ASKS[id]), tags: ["first-contact", "quality"],
      graders: {
        "first-reply--value-first": valueFirst,
        "task--fit-check": fitRubric(post),
        "honesty--no-invented-facts": honesty(p),
        "surface--mentions-local-mode": mentionsLocalMode,
        "surface--no-false-save-claim": noFalseSaveClaim,
        "activation--skill-fired": skillFired,
      },
    }); n++;
  }
  for (const t of CHAT_TASKS) {
    const p = personas[t.persona];
    const post = t.posting ? postings[t.posting] : null;
    writeCase(CHAT_SUITE, `chat-task-${t.task}-${t.persona}`, {
      description: p.why,
      prompt: post ? resumeAndPosting(p, post, t.ask) : `Here's my résumé:\n\n${p.body}\n\n${t.ask}`,
      tags: ["task", "quality"],
      graders: {
        [`task--${t.task}`]: taskRubric(t, post),
        "honesty--no-invented-facts": honesty(p),
        "surface--no-false-save-claim": noFalseSaveClaim,
        "activation--skill-fired": skillFired,
      },
    }); n++;
  }
  return n;
}

function buildTools() {
  resetSuite(TOOLS_SUITE);
  cpSync(join(here, "mocks", "empty"), join(TOOLS_SUITE, "mocks"), { recursive: true });
  let n = 0;
  for (const id of FIRST_CONTACT_POSTING_ONLY) {
    const post = postingFor(id);
    writeCase(TOOLS_SUITE, `tools-posting-only-${id}`, {
      description: "First contact with an empty Career KB and no résumé.",
      prompt: `${post.body}\n\nDo I fit this?`, tags: ["first-contact", "quality"],
      graders: {
        "first-reply--asks-for-one-thing": postingOnlyFirstReply,
        "trust--no-unasked-save": noUnaskedWrite("save_career_section"),
        "trust--no-unasked-pipeline-add": noUnaskedWrite("pipeline_add"),
        "activation--skill-fired": skillFired,
      },
    }); n++;
  }
  for (const [id, p] of Object.entries(personas)) {
    const post = postingFor(id);
    writeCase(TOOLS_SUITE, `tools-first-contact-${id}`, {
      description: p.why,
      prompt: resumeAndPosting(p, post, FIT_ASKS[id]), tags: ["first-contact", "quality"],
      graders: {
        "first-reply--value-first": valueFirst,
        "first-reply--offers-to-save": { type: "regex", pattern: "save|remember|keep (it|this|your)", flags: "i", weight: 0.5 },
        "task--fit-check": fitRubric(post),
        "honesty--no-invented-facts": honesty(p),
        "trust--no-unasked-save": noUnaskedWrite("save_career_section"),
        "trust--no-unasked-pipeline-add": noUnaskedWrite("pipeline_add"),
        "activation--skill-fired": skillFired,
      },
    }); n++;
  }
  const kbTruth = kbHonesty();
  for (const m of MEMORY_CASES) {
    const dir = writeCase(TOOLS_SUITE, m.id, {
      description: "Alex Rivera's Career KB is already saved; nothing is pasted.",
      prompt: m.ask, tags: ["memory", "quality"],
      graders: {
        "memory--uses-saved-history": { type: "regex", pattern: m.uses, flags: "i" },
        "memory--answer-from-kb": { type: "llm", weight: 2, body: `
The user's career history and job pipeline are saved in the assistant's tools. The user did not paste anything. A good answer is ${m.expect}.

PASS if the reply is built on specifics from the user's saved history or pipeline (named employers, real numbers, named applications) and does what the user asked.
FAIL if the reply asks the user to paste their résumé or background, gives generic advice that ignores the saved history, or does not do what the user asked.` },
        "honesty--no-invented-facts": kbTruth,
        "trust--no-unasked-save": noUnaskedWrite("save_career_section"),
        "activation--skill-fired": skillFired,
      },
    });
    cpSync(join(here, "mocks", "kb"), join(dir, "mocks"), { recursive: true });
    if (m.mocks) cpSync(join(here, "mocks", m.mocks), join(dir, "mocks"), { recursive: true });
    n++;
  }
  return n;
}

if (!existsSync(join(here, "mocks", "empty"))) {
  console.error("No recorded mocks. Run `npm run eval:mocks` first.");
  process.exit(1);
}
const chat = buildChat();
const tools = buildTools();
console.log(`${CHAT_SUITE}: ${chat} cases`);
console.log(`${TOOLS_SUITE}: ${tools} cases`);
